/* Encyclopedia glossary — part H: material selection & metals, stresses & stress analysis, CAD & CAE. */
TERMS_ADD('metals', [
    ['Material selection', 'اختيار المواد', 'Choosing the best material for a part by comparing what the job needs (strength, weight, heat, corrosion, wear) with what is available and what it costs. It is done together with the manufacturing method.', 'اختيار أفضل مادة لقطعة بمقارنة ما يحتاجه العمل (متانة ووزن وحرارة وتآكل وبلى) بما هو متوفر وبكلفته. ويتم مع طريقة التصنيع.'],
    ['Ferrous metals', 'المعادن الحديدية', 'Metals that are mainly iron: steels and cast irons. They are strong, cheap and usually magnetic, but most rust unless protected.', 'معادن أساسها الحديد: الفولاذ وحديد الزهر. قوية ورخيصة وعادةً مغناطيسية، لكن أغلبها يصدأ ما لم يُحمَ.'],
    ['Non-ferrous metals', 'المعادن غير الحديدية', 'Metals with no iron as the base, such as aluminium, copper, zinc, titanium and their alloys. Usually lighter or more corrosion-resistant, and not magnetic.', 'معادن لا يكون الحديد أساسها كالألمنيوم والنحاس والزنك والتيتانيوم وسبائكها. عادة أخف أو أقوى مقاومة للتآكل وغير مغناطيسية.'],
    ['Alloys', 'السبائك', 'A metal made by mixing two or more elements to get better properties than the pure metal, for example steel (iron + carbon), brass (copper + zinc) and bronze (copper + tin).', 'معدن يُصنع بمزج عنصرين أو أكثر للحصول على خواص أفضل من المعدن النقي، مثل الفولاذ (حديد + كربون) والنحاس الأصفر (نحاس + زنك) والبرونز (نحاس + قصدير).'],
    ['Carbon steel', 'الصلب الكربوني (الفولاذ)', 'Steel whose properties come mainly from its carbon content. Low carbon (under 0.25 %) is soft and weldable; high carbon (above 0.6 %) is hard and strong but less ductile. The most widely used steel.', 'فولاذ تأتي خواصه أساساً من محتواه من الكربون. المنخفض الكربون (أقل من 0.25 %) طري وقابل للحام والعالي (فوق 0.6 %) صلب وقوي لكنه أقل مطيلية. هو أكثر أنواع الفولاذ استخداماً.'],
    ['Alloy steel', 'الصلب السبائكي', 'Steel with added elements such as chromium, nickel, molybdenum or manganese to raise strength, hardenability, toughness or wear resistance. Used for shafts, gears and crankshafts.', 'فولاذ أُضيفت إليه عناصر كالكروم والنيكل والموليبدنوم والمنغنيز لرفع المتانة وقابلية التقسية والصلابة ومقاومة البلى. يُستخدم للأعمدة والتروس وأعمدة المرفق.'],
    ['Stainless steel', 'الصلب المقاوم للصدأ (الستانلس ستيل)', 'Steel with at least about 10.5 % chromium, which forms an invisible protective oxide film so it does not rust easily. Used for food, medical and chemical equipment.', 'فولاذ يحوي نحو 10.5 % كروم على الأقل يكوّن طبقة أكسيد واقية غير مرئية فلا يصدأ بسهولة. يُستخدم في معدات الأغذية والطب والكيماويات.'],
    ['Cast iron', 'حديد الزهر (السكب)', 'Iron with 2–4 % carbon that is easy to cast into complex shapes. It is hard, wear-resistant and damps vibration well, but it is brittle. Used for engine blocks and machine beds.', 'حديد فيه 2–4 % كربون يسهل صبه بأشكال معقدة. صلب ومقاوم للبلى ويخمد الاهتزاز جيداً لكنه هش. يُستخدم لكتل المحركات وقواعد الآلات.'],
    ['Aluminum alloys', 'سبائك الألومنيوم', 'Light alloys (about one third the density of steel) with good corrosion resistance and heat and electrical conduction. Used in aircraft, cars, frames and heat sinks.', 'سبائك خفيفة (نحو ثلث كثافة الفولاذ) مقاومة جيدة للتآكل وموصلية حرارية وكهربائية جيدة. تُستخدم في الطائرات والسيارات والهياكل ومشتتات الحرارة.'],
    ['Copper alloys', 'سبائك النحاس', 'Alloys based on copper, such as brass and bronze. They conduct electricity and heat well, resist corrosion and wear, and are easy to machine.', 'سبائك أساسها النحاس كالنحاس الأصفر والبرونز. توصل الكهرباء والحرارة جيداً وتقاوم التآكل والبلى وتُشغّل بسهولة.'],
    ['Brass', 'النحاس الأصفر (الشبه)', 'An alloy of copper and zinc. It is easy to machine, corrodes slowly and looks golden. Used for valves, fittings, taps and musical instruments.', 'سبيكة نحاس وزنك. تُشغّل بسهولة وتتآكل ببطء ولونها ذهبي. تُستخدم للصمامات والوصلات والحنفيات والآلات الموسيقية.'],
    ['Bronze', 'البرونز', 'An alloy of copper mainly with tin (or aluminium). It is hard, wear-resistant and low in friction, so it is used for bushings, bearings, gears, bells and ship propellers.', 'سبيكة نحاس مع قصدير غالباً (أو ألمنيوم). صلب ومقاوم للبلى وقليل الاحتكاك لذا يُستخدم للجلب والمحامل والتروس والأجراس ومراوح السفن.'],
    ['Titanium alloys', 'سبائك التيتانيوم', 'Alloys as strong as many steels but about 45 % lighter, with excellent corrosion resistance and good behaviour at heat. Costly and hard to machine. Used in aerospace, implants and racing.', 'سبائك بقوة كثير من الفولاذ لكنها أخف بنحو 45 % ومقاومتها للتآكل ممتازة وسلوكها جيد في الحرارة. غالية وصعبة التشغيل. تُستخدم في الطيران والغرسات الطبية والسباقات.'],
    ['Superalloys', 'السبائك الفائقة', 'Nickel-, cobalt- or iron-based alloys that keep strength and resist oxidation at very high temperature (over 700 °C). Used for jet engine and gas turbine blades.', 'سبائك أساسها النيكل أو الكوبالت أو الحديد تحافظ على متانتها وتقاوم الأكسدة في حرارة عالية جداً (فوق 700 °م). تُستخدم لريش محركات الطائرات والتوربينات الغازية.'],
    ['Polymers', 'البوليمرات (المواد البلاستيكية)', 'Materials made of long chain molecules: thermoplastics (soften when heated, like nylon), thermosets (set permanently, like epoxy) and rubbers. Light, corrosion-free and easy to mould, but weaker and less heat-resistant than metals.', 'مواد من جزيئات سلسلية طويلة: لدائن حرارية (تلين بالتسخين كالنايلون) ولدائن متصلدة (تتصلب نهائياً كالإيبوكسي) ومطاط. خفيفة ولا تتآكل وسهلة القولبة لكنها أضعف وأقل تحملاً للحرارة من المعادن.'],
    ['Ceramics', 'السيراميك (الخزف)', 'Hard, heat-resistant, non-metallic materials such as alumina, silicon carbide and porcelain. Very hard and wear-resistant, but brittle. Used for cutting tools, bearings, insulators and furnace linings.', 'مواد صلبة مقاومة للحرارة غير معدنية كالألومينا وكربيد السيليكون والخزف. شديدة الصلادة ومقاومة للبلى لكنها هشة. تُستخدم لأدوات القطع والمحامل والعوازل وبطانات الأفران.'],
    ['Composites', 'المواد المركبة (المؤلفة)', 'Materials combining two or more different materials, such as fibres in a resin (carbon fibre, fibreglass), to get high strength with low weight. Used in aircraft, boats and sports equipment.', 'مواد تجمع مادتين مختلفتين أو أكثر، كالألياف في راتنج (ألياف الكربون والزجاج)، للحصول على متانة عالية بوزن منخفض. تُستخدم في الطائرات والقوارب والمعدات الرياضية.'],
    ['Fatigue resistance', 'مقاومة الكلال (التعب)', 'How long a material survives repeated loading. It is described by the endurance limit and improved by smooth surfaces, rounded corners, shot peening and clean material.', 'مدى بقاء المادة تحت التحميل المتكرر. يُوصف بحد التحمل ويتحسن بالأسطح الناعمة والزوايا المدورة والصنفرة بالكرات والمادة النظيفة.'],
    ['Corrosion resistance', 'مقاومة التآكل', 'The ability of a material to resist chemical attack from air, water, salts and acids. Gained by choosing stainless steel, aluminium or bronze, or by painting, plating and coating.', 'قدرة المادة على مقاومة الهجوم الكيميائي من الهواء والماء والأملاح والأحماض. تُكتسب باختيار الفولاذ المقاوم للصدأ أو الألمنيوم أو البرونز أو بالدهان والطلاء الكهربائي والتغطية.']
]);

TERMS_ADD('materials', [
    ['Tensile stress', 'إجهاد الشد', 'Stress caused by forces that try to stretch a part, acting normal to the cross-section. A rope or a bolt shank pulled by a load is in tension.', 'إجهاد ناتج عن قوى تحاول مد القطعة، وتؤثر عمودياً على المقطع. الحبل أو ساق البرغي المسحوب بحمل في حالة شد.', 'σ = F / A'],
    ['Compressive stress', 'إجهاد الضغط', 'Stress caused by forces that try to squeeze a part shorter. A column or a short block under a load is in compression. Long slender parts may buckle instead.', 'إجهاد ناتج عن قوى تحاول ضغط القطعة وتقصيرها. العمود أو الكتلة القصيرة تحت حمل في حالة ضغط. أما القطع الطويلة النحيلة فقد تنبعج.', 'σ = −F / A'],
    ['Torsional stress', 'إجهاد الالتواء', 'Shear stress inside a shaft that is twisted by a torque. It is zero at the centre and largest at the outer surface.', 'إجهاد قص داخل عمود يلويه عزم. ينعدم في المركز ويكون أكبر ما يمكن على السطح الخارجي.', 'τ = T · r / J'],
    ['Bending stress', 'إجهاد الانحناء', 'Stress in a beam bent by loads: tension on one side, compression on the other and zero at the neutral axis. It is largest at the outer fibres at the point of the maximum moment.', 'إجهاد في عارضة تنحني تحت الأحمال: شد على جانب وضغط على الآخر وصفر عند المحور المحايد. يبلغ أكبر قيمة في الألياف الخارجية عند نقطة العزم الأعظم.', 'σ = M · y / I'],
    ['Normal stress', 'الإجهاد الطبيعي (العمودي)', 'Stress acting perpendicular to a surface, either tension or compression. It differs from shear stress, which acts along the surface.', 'إجهاد يؤثر عمودياً على سطح، شداً كان أو ضغطاً. يختلف عن إجهاد القص الذي يؤثر على امتداد السطح.'],
    ['Creep', 'الزحف', 'Slow permanent stretching of a material under constant load, mainly at high temperature and over a long time, even when the stress is below the yield strength. Critical for boilers and turbines.', 'استطالة دائمة بطيئة لمادة تحت حمل ثابت، خاصة عند الحرارة العالية وعلى مدى زمن طويل حتى لو كان الإجهاد أقل من حد الخضوع. حرج للمراجل والتوربينات.'],
    ['Elastic deformation', 'التشوه المرن', 'Change of shape that disappears completely when the load is removed, like a spring returning to its length. It follows Hooke\'s law.', 'تغير في الشكل يزول تماماً عند إزالة الحمل كعودة نابض إلى طوله. يتبع قانون هوك.'],
    ['Plastic deformation', 'التشوه اللدن', 'Permanent change of shape that remains after the load is removed. It starts when the stress passes the yield strength. Forming processes such as bending and forging use it on purpose.', 'تغير دائم في الشكل يبقى بعد إزالة الحمل. يبدأ عندما يتجاوز الإجهاد حد الخضوع. تستخدمه عمداً عمليات التشكيل كالثني والطرق.'],
    ['Hooke\'s law', 'قانون هوك', 'Within the elastic range, stress is proportional to strain (and a spring\'s extension is proportional to the force). The constant is the modulus of elasticity.', 'ضمن المجال المرن يتناسب الإجهاد طرداً مع الانفعال (واستطالة النابض مع القوة). الثابت هو معامل المرونة.', 'σ = E · ε  ;  F = k · x'],
    ['Poisson\'s ratio', 'نسبة بواسون', 'When a bar is stretched it also gets thinner. Poisson\'s ratio is the ratio of the sideways shrinking strain to the lengthwise stretching strain. For most metals it is about 0.3.', 'عندما يُمد قضيب يصبح أرفع أيضاً. نسبة بواسون هي نسبة انفعال الانكماش الجانبي إلى انفعال الاستطالة الطولي. وهي نحو 0.3 لأغلب المعادن.', 'ν = − ε_lateral / ε_axial'],
    ['Shear modulus', 'معامل القص', 'The stiffness of a material in shear: ratio of shear stress to shear strain. It is related to Young\'s modulus and Poisson\'s ratio. Steel is about 80 GPa.', 'صلابة المادة في القص: نسبة إجهاد القص إلى انفعال القص. يرتبط بمعامل يونغ ونسبة بواسون. للفولاذ نحو 80 GPa.', 'G = E / (2 · (1 + ν))'],
    ['Stress concentration', 'تركيز الإجهاد', 'Local rise of stress around holes, notches, sharp corners and sudden changes of section. The peak is the nominal stress times a factor Kt. It starts fatigue cracks, so use fillets and smooth transitions.', 'ارتفاع موضعي في الإجهاد حول الثقوب والشقوق والزوايا الحادة والتغيرات المفاجئة في المقطع. القمة تساوي الإجهاد الاسمي مضروباً بمعامل Kt. تبدأ منها شقوق الكلل لذا تُستخدم الأقواس والانتقالات الناعمة.', 'σ_max = K_t · σ_nom'],
    ['Stress–strain curve', 'مخطط الإجهاد والانفعال', 'A graph of stress σ (vertical axis) against strain ε (horizontal axis) obtained from a tensile test. Its shape shows how a material responds to load: its stiffness, strength, ductility and toughness. The first figure below is a schematic <b>engineering</b> curve of a ductile steel (blue) and a brittle material (orange); the second compares four material types. How to obtain the curve from test data is explained on the <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encTest(\'tensile\')">Tensile test page</a> (with a data table), not repeated here.<span style="display:block;margin-top:.5rem"><b>Also called:</b> stress–strain curve (Arabic: منحنى الإجهاد والانفعال, مخطط الإجهاد والانفعال) — the two Arabic names are used for the same diagram.</span><span style="display:block;margin-top:.5rem"><b>Stages (numbers in figure 1):</b> <b>1 Elastic range</b> from O to P — straight line, strain disappears on unloading; its slope is Young\'s modulus E. <b>P</b> proportional limit (end of the straight line); the <i>elastic limit</i> (where permanent strain begins) is usually very close to it and is distinguished only in some references. <b>2 Yielding</b> at Y: permanent (plastic) strain starts. <b>3 Strain hardening</b> up to <b>U</b>, the ultimate tensile strength σ<sub>u</sub> (highest engineering stress). <b>4 Necking</b>: the cross-section narrows locally and the engineering stress falls until fracture at <b>F</b>.</span><span style="display:block;margin-top:.5rem"><b>Depends on the material and the test:</b> low-carbon steel shows a sharp upper/lower yield and a plateau; aluminium, copper and stainless steel yield gradually, so the 0.2 % offset yield strength is used; cast iron, glass and ceramics are almost linear to fracture with no yield or necking; rubber is nonlinear elastic to very large strains (figure 2, curve 4); polymers are viscoelastic, so the curve changes with strain rate and temperature. Never generalise the curve of one ductile metal to all materials.</span><span style="display:block;margin-top:.5rem"><b>Ductile vs brittle (figure 2):</b> a ductile metal (1, 2) deforms plastically, necks and gives warning before fracture and has a large area under the curve (high toughness). A brittle material (3) fractures near the end of the elastic range with a small area; its tensile strength is usually well below its compressive strength and depends strongly on flaws.</span><span style="display:block;margin-top:.5rem"><b>Unloading (green dashed in figure 1):</b> unloading from a point beyond yield follows a line parallel to the elastic slope; the strain recovered is elastic, the strain left at zero stress is the permanent strain ε<sub>p</sub>.</span><span style="display:block;margin-top:.5rem"><b>Engineering vs true values:</b> engineering stress and strain use the original area A₀ and length L₀. True values use the instantaneous area and length; they are about equal at small strain and are related by σ<sub>true</sub> = σ(1+ε) and ε<sub>true</sub> = ln(1+ε), valid until necking (they assume constant volume and uniform deformation). True stress keeps rising during necking even though the engineering curve falls.</span><span style="display:block;margin-top:.5rem"><b>Slope and area:</b> the slope of the straight part is the modulus E, a material property that is not the same as the stiffness of a part (<a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Stiffness\',\'matprops\')">Stiffness</a>). The area under the curve is energy per unit volume: up to yield it is the modulus of resilience σ<sub>y</sub>²/(2E); up to fracture it is the modulus of toughness (<a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Toughness\',\'matprops\')">Toughness</a>).</span><span style="display:block;margin-top:.5rem"><b>Worked example (steel bar, data in the <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encTest(\'tensile\')">Tensile test page</a>):</b> A₀ = 122.7 mm², L₀ = 50 mm. (a) From the first points σ = 325.9 MPa at ε = 0.00163 → E = 325.9 / 0.00163 ≈ 200 GPa. (b) Yield σ<sub>y</sub> = 360 MPa; modulus of resilience U<sub>r</sub> = 360² / (2 × 200 000) = 0.324 MJ/m³. (c) Maximum point: σ<sub>u</sub> = 540 MPa at ε = 0.18 → true values σ<sub>true</sub> = 540 × 1.18 = 637 MPa, ε<sub>true</sub> = ln 1.18 = 0.166. (d) Area up to fracture (ε<sub>f</sub> = 0.25): trapezoids on the table give ≈ 118 MJ/m³; the shortcut ½(σ<sub>y</sub> + σ<sub>u</sub>)·ε<sub>f</sub> = 112.5 MJ/m³ — the same order. The data are teaching values, not a certified test.</span><span style="display:block;margin-top:.5rem"><b>Related properties:</b> <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Elasticity\',\'matprops\')">Elasticity</a> · <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Plasticity\',\'matprops\')">Plasticity</a> · <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Ductility\',\'matprops\')">Ductility</a> · <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Brittleness\',\'matprops\')">Brittleness</a> · <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Toughness\',\'matprops\')">Toughness</a> · <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Stiffness\',\'matprops\')">Stiffness</a> · <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Modulus of elasticity\',\'matprops\')">Young\'s modulus</a> · <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Yield strength\',\'matprops\')">Yield strength</a> · <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Ultimate tensile strength\',\'matprops\')">Ultimate tensile strength</a> · <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Plastic deformation\',\'matprops\')">Plastic deformation</a> · <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Elastic deformation\',\'matprops\')">Elastic deformation</a></span><span style="display:block;margin-top:.5rem"><b>References:</b> Callister &amp; Rethwisch; Hibbeler; Dieter; ASTM E8/E8M, ISO 6892-1.</span>', 'رسم بياني للإجهاد σ (المحور الرأسي) مقابل الانفعال ε (المحور الأفقي) يُستخرج من اختبار الشد. يبيّن شكله استجابة المادة للحمل: صلابتها ومقاومتها ومطيليتها ومتانتها. الشكل الأول أدناه تخطيطي لمنحنى <b>هندسي</b> لفولاذ مطيل (أزرق) ولمادة قصفة (برتقالي)، والثاني يقارن أربعة أنواع من المواد. أما كيفية استخراج المنحنى من بيانات الاختبار فتُشرح في <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encTest(\'tensile\')">صفحة اختبار الشد</a> (مع جدول بيانات) ولا تتكرر هنا.<span style="display:block;margin-top:.5rem"><b>تسميات أخرى:</b> منحنى الإجهاد والانفعال (Stress–strain curve) — الاسمان «مخطط» و«منحنى» يُستعملان للرسم نفسه.</span><span style="display:block;margin-top:.5rem"><b>المراحل (الأرقام في الشكل 1):</b> <b>1 المجال المرن</b> من O إلى P — خط مستقيم يزول فيه الانفعال عند رفع الحمل، وميله معامل يونغ E. <b>P</b> حد التناسب (نهاية الخط المستقيم)؛ أما <i>حد المرونة</i> (حيث يبدأ التشوه الدائم) فهو عادة قريب جداً منه ولا يُميَّز إلا في بعض المراجع. <b>2 الخضوع</b> عند Y: يبدأ الانفعال اللدن (الدائم). <b>3 التصلد بالتشوه</b> حتى <b>U</b> وهو مقاومة الشد القصوى σ<sub>u</sub> (أعلى إجهاد هندسي). <b>4 التخصر (العنق)</b>: يضيق المقطع موضعياً ويهبط الإجهاد الهندسي حتى الكسر عند <b>F</b>.</span><span style="display:block;margin-top:.5rem"><b>يختلف باختلاف المادة وظروف الاختبار:</b> يُظهر الفولاذ منخفض الكربون حد خضوع علوياً وسفلياً وهضبة؛ ويخضع الألمنيوم والنحاس والفولاذ المقاوم للصدأ تدريجياً فيُستعمل حد الخضوع بإزاحة 0.2%؛ وحديد الزهر والزجاج والسيراميك شبه خطية حتى الكسر دون خضوع أو تخصر؛ والمطاط مرن غير خطي حتى انفعالات كبيرة جداً (الشكل 2، المنحنى 4)؛ واللدائن لزجة–مرنة فيتغير المنحنى مع معدل الانفعال والحرارة. لا يجوز تعميم منحنى معدن مطيل واحد على كل المواد.</span><span style="display:block;margin-top:.5rem"><b>المطيل مقابل القصف (الشكل 2):</b> المعدن المطيل (1 و2) يتشوه لدناً ويتخصر ويعطي إنذاراً قبل الكسر ومساحته تحت المنحنى كبيرة (متانة عالية). أما المادة القصفة (3) فتنكسر قرب نهاية المجال المرن بمساحة صغيرة؛ ومقاومتها شدّاً أقل عادة بكثير من مقاومتها ضغطاً وتعتمد بشدة على العيوب.</span><span style="display:block;margin-top:.5rem"><b>التفريغ (الخط الأخضر المتقطع في الشكل 1):</b> يسير التفريغ من نقطة بعد الخضوع على خط موازٍ للميل المرن؛ الانفعال المستعاد مرن، والباقي عند إجهاد صفر هو الانفعال الدائم ε<sub>p</sub>.</span><span style="display:block;margin-top:.5rem"><b>الهندسي مقابل الحقيقي:</b> يستعمل الإجهاد والانفعال الهندسيان المساحة الأصلية A₀ والطول الأصلي L₀. أما الحقيقيان فيستعملان المساحة والطول اللحظيين؛ يتساويان تقريباً عند الانفعال الصغير ويرتبطان بـ σ<sub>true</sub> = σ(1+ε) وε<sub>true</sub> = ln(1+ε) وهما صالحان حتى بدء التخصر (ويفترضان حجماً ثابتاً وتشوهاً منتظماً). ويواصل الإجهاد الحقيقي الارتفاع أثناء التخصر رغم هبوط المنحنى الهندسي.</span><span style="display:block;margin-top:.5rem"><b>الميل والمساحة:</b> ميل الجزء المستقيم هو المعامل E، وهو خاصية مادة وليس صلابة القطعة (<a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'الصلابة\',\'matprops\')">الصلابة</a>). والمساحة تحت المنحنى طاقة لكل وحدة حجم: حتى الخضوع هي معامل المرونة الطاقي (الريزيليانس) σ<sub>y</sub>²/(2E)، وحتى الكسر هي معامل المتانة (<a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'المتانة\',\'matprops\')">المتانة</a>).</span><span style="display:block;margin-top:.5rem"><b>مثال محلول (قضيب فولاذ، بياناته في <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encTest(\'tensile\')">صفحة اختبار الشد</a>):</b> A₀ = 122.7 mm² وL₀ = 50 مم. (أ) من أول النقاط σ = 325.9 MPa عند ε = 0.00163 ← E = 325.9 / 0.00163 ≈ 200 GPa. (ب) الخضوع σ<sub>y</sub> = 360 MPa؛ معامل المرونة الطاقي U<sub>r</sub> = 360² / (2 × 200 000) = 0.324 MJ/m³. (ج) النقطة العظمى: σ<sub>u</sub> = 540 MPa عند ε = 0.18 ← القيمتان الحقيقيتان σ<sub>true</sub> = 540 × 1.18 = 637 MPa وε<sub>true</sub> = ln 1.18 = 0.166. (د) المساحة حتى الكسر (ε<sub>f</sub> = 0.25): المعيّنات الشبه منحرفة على الجدول تعطي ≈ 118 MJ/m³؛ والاختصار ½(σ<sub>y</sub> + σ<sub>u</sub>)·ε<sub>f</sub> = 112.5 MJ/m³ — من الرتبة نفسها. والبيانات قيم تعليمية وليست اختباراً معتمداً.</span><span style="display:block;margin-top:.5rem"><b>خواص ذات صلة:</b> <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'المرونة\',\'matprops\')">المرونة</a> · <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'اللدونة\',\'matprops\')">اللدونة</a> · <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'المطيلية\',\'matprops\')">المطيلية</a> · <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'الهشاشية\',\'matprops\')">القصف (الهشاشية)</a> · <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'المتانة\',\'matprops\')">المتانة</a> · <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'الصلابة\',\'matprops\')">الصلابة</a> · <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'معامل المرونة\',\'matprops\')">معامل يونغ</a> · <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'حد الخضوع\',\'matprops\')">حد الخضوع</a> · <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'مقاومة الشد القصوى\',\'matprops\')">مقاومة الشد القصوى</a> · <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'التشوه اللدن\',\'matprops\')">التشوه اللدن</a> · <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'التشوه المرن\',\'matprops\')">التشوه المرن</a></span><span style="display:block;margin-top:.5rem"><b>المراجع:</b> Callister &amp; Rethwisch؛ Hibbeler؛ Dieter؛ ASTM E8/E8M وISO 6892-1.</span>', '<svg viewBox="0 0 360 236" role="img" aria-label="Stress–strain diagram / مخطط الإجهاد والانفعال" style="width:100%;max-width:440px;height:auto;display:block;margin:0 auto 6px" font-family="sans-serif" font-size="11" fill="currentColor"><g stroke="currentColor" stroke-width="1.3" fill="none"><path d="M40 204V16M40 204H344"/><path d="M40 12l-3.5 8h7zM348 204l-8-3.5v7z" fill="currentColor"/></g><text x="22" y="22">σ</text><text x="340" y="222">ε</text><text x="30" y="216">O</text><g stroke-dasharray="3 3" stroke="currentColor" stroke-width="0.8" opacity="0.55" fill="none"><path d="M40 96H108M40 40H252M300 66V204M252 40V204"/></g><path d="M40 204L100 96L106 88L112 98H150C190 98 225 44 252 40C270 38 286 52 300 66" fill="none" stroke="#2563eb" stroke-width="2.4"/><path d="M215 62L140 204" fill="none" stroke="#10b981" stroke-width="1.6" stroke-dasharray="5 3"/><path d="M40 204L118 124" fill="none" stroke="#f59e0b" stroke-width="2" stroke-dasharray="6 3"/><text x="100" y="152" fill="#f59e0b">brittle ×</text><circle cx="100" cy="96" r="3"/><circle cx="106" cy="88" r="3"/><circle cx="252" cy="40" r="3"/><circle cx="300" cy="66" r="3"/><circle cx="215" cy="62" r="3" fill="#10b981"/><text x="86" y="112">P</text><text x="110" y="82">Y</text><text x="256" y="34">U</text><text x="304" y="62">F ×</text><text x="8" y="100">σ<tspan font-size="8" dy="3">y</tspan></text><text x="8" y="44">σ<tspan font-size="8" dy="3">u</tspan></text><text x="140" y="219" fill="#10b981">ε<tspan font-size="8" dy="3">p</tspan></text><text x="58" y="160">E</text><g font-size="10" font-weight="bold"><text x="66" y="188">1</text><text x="126" y="116">2</text><text x="175" y="86">3</text><text x="278" y="46">4</text></g></svg><svg viewBox="0 0 360 226" role="img" aria-label="Comparison of stress–strain curves / مقارنة منحنيات الإجهاد والانفعال" style="width:100%;max-width:440px;height:auto;display:block;margin:0 auto 6px" font-family="sans-serif" font-size="11" fill="currentColor"><g stroke="currentColor" stroke-width="1.3" fill="none"><path d="M40 200V16M40 200H344"/><path d="M40 12l-3.5 8h7zM348 200l-8-3.5v7z" fill="currentColor"/></g><text x="22" y="22">σ</text><text x="340" y="218">ε</text><path d="M40 200L84 106L88 100L94 106H124C150 106 190 58 226 46C246 40 254 54 266 74" fill="none" stroke="#2563eb" stroke-width="2.3"/><path d="M40 200L92 140C108 110 138 94 176 88C208 84 226 90 238 102" fill="none" stroke="#10b981" stroke-width="2.3"/><path d="M40 200L100 90" fill="none" stroke="#ef4444" stroke-width="2.3"/><path d="M40 200C120 198 200 190 260 176C300 166 326 150 336 132" fill="none" stroke="#f59e0b" stroke-width="2.3"/><g stroke="currentColor" stroke-width="2"><path d="M262 70l8 8m0-8l-8 8"/><path d="M234 98l8 8m0-8l-8 8"/><path d="M96 86l8 8m0-8l-8 8"/><path d="M332 128l8 8m0-8l-8 8"/></g><g font-size="12" font-weight="bold"><text x="268" y="62" fill="#2563eb">1</text><text x="244" y="96" fill="#10b981">2</text><text x="108" y="84" fill="#ef4444">3</text><text x="300" y="150" fill="#f59e0b">4</text></g></svg>σ = F / A₀  [Pa, MPa] · ε = ΔL / L₀ = (L − L₀) / L₀  [–]<br>σ = E · ε  (linear elastic range) · E = slope [GPa]<br>σ_true = σ·(1 + ε) · ε_true = ln(1 + ε)  (until necking)<br>U_r = σ_y² / (2E) · U_T = ∫ σ dε  [J/m³]<br>P: proportional limit · Y: yield · U: ultimate strength σ_u · F: fracture · ε_p: permanent strain'],
    ['Allowable stress', 'الإجهاد المسموح به', 'The highest stress a designer permits in a part in service: the strength of the material divided by the factor of safety.', 'أعلى إجهاد يسمح به المصمم في قطعة أثناء الخدمة: متانة المادة مقسومة على معامل الأمان.', 'σ_allow = σ_yield / FoS'],
    ['Thermal stress', 'الإجهاد الحراري', 'Stress that appears when a part cannot expand or contract freely with temperature change, for example a rail or a pipe held between fixed ends.', 'إجهاد ينشأ عندما لا تستطيع القطعة التمدد أو الانكماش بحرية مع تغير الحرارة، كسكة أو أنبوب مثبت بين نهايتين ثابتتين.', 'σ = E · α · ΔT'],
    ['Finite Element Analysis (FEA)', 'تحليل العناصر المحدودة', 'A computer method that divides a part into many small elements and solves the equations for each to find stress, deflection, heat flow or vibration of complex shapes under loads.', 'طريقة حاسوبية تقسم القطعة إلى عناصر صغيرة كثيرة وتحل المعادلات لكل منها لإيجاد الإجهاد والتدلي وتدفق الحرارة أو اهتزاز أشكال معقدة تحت الأحمال.'],
    ['Von Mises stress', 'إجهاد فون ميزس', 'One equivalent stress that combines all the stress components at a point. If it stays below the yield strength of a ductile material, the point does not yield. Used by FEA programs for the colour plots.', 'إجهاد مكافئ واحد يجمع كل مركبات الإجهاد في نقطة. إذا بقي أقل من حد الخضوع لمادة مطيلية فلن تخضع النقطة. تستخدمه برامج FEA في الرسوم الملونة.', 'σ_vm = √(σ₁² − σ₁σ₂ + σ₂²)']
]);

TERMS_ADD('cadcae', [
    ['Computer-Aided Engineering (CAE)', 'الهندسة بمساعدة الحاسوب', 'Using software to analyse and simulate designs: strength (FEA), flow and heat (CFD), motion and vibration, before anything is built. It finds problems early and cuts testing cost.', 'استخدام البرمجيات لتحليل التصاميم ومحاكاتها: المتانة (FEA) والتدفق والحرارة (CFD) والحركة والاهتزاز قبل بناء أي شيء. تكشف المشاكل مبكراً وتخفض كلفة الاختبار.'],
    ['Computational Fluid Dynamics (CFD)', 'ديناميكا السوائل الحسابية', 'Computer simulation of liquid and gas flow, pressure, speed and heat transfer around and inside a design, such as air over a car, water in a pump or cooling of a chip.', 'محاكاة حاسوبية لجريان السوائل والغازات والضغط والسرعة وانتقال الحرارة حول التصميم وداخله، كالهواء على سيارة أو الماء في مضخة أو تبريد شريحة.'],
    ['3D modeling', 'النمذجة ثلاثية الأبعاد', 'Building a part as a solid or surface model in the computer, so it can be rotated, measured, analysed, drawn automatically and sent to CNC or a 3D printer.', 'بناء قطعة كنموذج صلب أو سطحي في الحاسوب فيمكن تدويرها وقياسها وتحليلها ورسمها آلياً وإرسالها إلى CNC أو طابعة ثلاثية الأبعاد.'],
    ['2D drafting', 'الرسم ثنائي الأبعاد', 'Making flat technical drawings with lines, arcs and dimensions in CAD, such as plans and part drawings. It is still the standard way to give manufacturing information.', 'إعداد مخططات فنية مسطحة بخطوط وأقواس وأبعاد في CAD كالمخططات الأرضية ومخططات القطع. ما زال الأسلوب المعياري لإعطاء معلومات التصنيع.'],
    ['Assembly modeling', 'نمذجة التجميعات', 'Putting 3D parts together in CAD with mates (coincident, concentric, distance) to build a whole machine, check fit and motion, and create the bill of materials.', 'تجميع قطع ثلاثية الأبعاد في CAD بواسطة قيود (تطابق وتحاذٍ ومسافة) لبناء آلة كاملة وفحص التركيب والحركة وإنشاء جدول المواد.'],
    ['Parametric design', 'التصميم البارامتري', 'A model driven by parameters (dimensions and rules). Change one value, such as a hole diameter or length, and the whole model and its drawings update automatically.', 'نموذج تحركه بارامترات (أبعاد وقواعد). تغير قيمة واحدة كقطر ثقب أو طول فيتحدث النموذج كله ومخططاته تلقائياً.'],
    ['Mesh generation', 'توليد الشبكة (التحليلية)', 'Dividing the 3D model into many small elements (triangles, tetrahedra, hexahedra) for analysis. Finer mesh near sharp corners and holes gives more accurate results but takes longer to solve.', 'تقسيم النموذج ثلاثي الأبعاد إلى عناصر صغيرة كثيرة (مثلثات ورباعيات وجوه وسداسيات) للتحليل. الشبكة الأدق قرب الزوايا والثقوب تعطي نتائج أدق لكنها تحتاج حلاً أطول.'],
    ['Boundary conditions', 'الشروط الحدية', 'What is known at the edges of a model: where it is fixed, supported or free, what the temperature or pressure is. Wrong boundary conditions give wrong results, however good the mesh.', 'ما هو معروف عند حدود النموذج: أين هو مثبت أو مسنود أو حر وما الحرارة أو الضغط. الشروط الحدية الخاطئة تعطي نتائج خاطئة مهما كانت الشبكة جيدة.'],
    ['Load application', 'تطبيق الأحمال', 'Defining the forces, pressures, torques, gravity, heat or motion acting on the model in a simulation, with the right size, direction and place, as in real service.', 'تحديد القوى والضغوط والعزوم والجاذبية والحرارة أو الحركة المؤثرة على النموذج في المحاكاة بالمقدار والاتجاه والمكان الصحيحين كما في الخدمة الفعلية.'],
    ['Simulation', 'المحاكاة', 'Imitating how a machine or process behaves with a computer model to predict results, test ideas and find limits without building or breaking real parts.', 'تقليد سلوك آلة أو عملية بنموذج حاسوبي للتنبؤ بالنتائج واختبار الأفكار ومعرفة الحدود دون بناء قطع حقيقية أو كسرها.'],
    ['Stress visualization', 'تصور الإجهادات', 'Showing stress results as a colour map on the model, blue for low and red for high, so the weak spots, stress concentrations and over-designed regions can be seen at a glance.', 'عرض نتائج الإجهاد كخريطة ألوان على النموذج: الأزرق للمنخفض والأحمر للمرتفع، فتظهر النقاط الضعيفة وتراكز الإجهاد والمناطق المبالغ في تصميمها بنظرة.'],
    ['Deformation analysis', 'تحليل التشوه', 'Calculating how much and in which direction a part moves or bends under load, shown (often exaggerated) on the model. Used to check stiffness and clearances.', 'حساب مقدار واتجاه حركة أو انحناء قطعة تحت الحمل، ويُعرض (غالباً مضخماً) على النموذج. يُستخدم لفحص الصلابة والخلوصات.'],
    ['Thermal analysis', 'التحليل الحراري', 'Calculating temperatures and heat flow in a part or assembly from heat sources, convection and radiation, and (together with stress analysis) the thermal stresses they cause.', 'حساب الحرارة وتدفقها في قطعة أو تجميعة بدلالة مصادر الحرارة والحمل والإشعاع، ومع التحليل الإنشائي الإجهادات الحرارية الناتجة.'],
    ['Fatigue analysis', 'تحليل الكلال', 'Predicting how many load cycles a part will survive, or its safety against fatigue, from the stress history, material S–N data and stress concentrations.', 'التنبؤ بعدد دورات الحمل التي ستتحملها القطعة أو أمانها ضد الكلال انطلاقاً من تاريخ الإجهاد وبيانات S–N للمادة وتراكز الإجهاد.'],
    ['Kinematic simulation', 'محاكاة الحركة (الكينماتيكية)', 'Animating a mechanism to see the paths, speeds and accelerations of its parts and to detect collisions, without considering forces. Used for linkages, cams and robots.', 'تحريك آلية لرؤية مسارات أجزائها وسرعاتها وتسارعاتها وكشف التصادمات دون النظر إلى القوى. تُستخدم للوصلات والكامات والروبوتات.'],
    ['Topology optimization', 'تحسين الشكل الطوبولوجي', 'A software method that removes material where it is not needed and keeps it where loads travel, giving a light, strong organic shape for a given load and space.', 'طريقة برمجية تزيل المادة من حيث لا حاجة لها وتبقيها حيث تسري الأحمال فتعطي شكلاً عضوياً خفيفاً وقوياً لحمل وحيز معينين.'],
    ['Generative design', 'التصميم التوليدي', 'The computer creates many design options automatically from goals and constraints (load, material, cost, process) and the engineer picks the best. Often combined with 3D printing.', 'يولد الحاسوب خيارات تصميم كثيرة تلقائياً من الأهداف والقيود (حمل ومادة وكلفة وطريقة تصنيع) ثم يختار المهندس الأفضل. يُجمع غالباً مع الطباعة ثلاثية الأبعاد.'],
    ['Digital twin', 'التوأم الرقمي', 'A live virtual copy of a real machine or plant, fed with sensor data, that shows its current condition and lets engineers predict wear, test changes and plan maintenance.', 'نسخة افتراضية حية من آلة أو مصنع حقيقي تُغذّى ببيانات الحساسات وتبين حالتها الراهنة وتتيح للمهندسين التنبؤ بالبلى واختبار التغييرات وتخطيط الصيانة.'],
    ['Render', 'الإظهار الفني (الرندر)', 'Producing a realistic image of a 3D model with materials, light and shadows. Used for presentations, catalogues and design reviews.', 'إنتاج صورة واقعية لنموذج ثلاثي الأبعاد بمواد وإضاءة وظلال. تُستخدم في العروض والكتالوجات ومراجعات التصميم.'],
    ['Animation', 'الرسوم المتحركة (الحركية)', 'Moving the parts of a model over time to show how a machine works, assembles or comes apart, for training, manuals and sales.', 'تحريك أجزاء النموذج عبر الزمن لإظهار كيف تعمل الآلة أو تتركب أو تتفكك، للتدريب والأدلة والمبيعات.'],
    ['File format', 'صيغة الملف', 'The type of file a CAD or CAE model is saved in. Native formats belong to one program; neutral formats exchange between programs: STEP and IGES (3D models), STL (3D printing), DXF/DWG (2D drawings).', 'نوع الملف الذي يُحفظ به نموذج CAD أو CAE. الصيغ الأصلية تخص برنامجاً واحداً؛ والمحايدة تتبادل بين البرامج: STEP وIGES (نماذج ثلاثية) وSTL (الطباعة ثلاثية الأبعاد) وDXF/DWG (رسوم ثنائية).'],
    ['Interference check', 'فحص التداخل', 'An automatic check in an assembly for parts that occupy the same space or touch where they should not. Catches design mistakes before manufacture.', 'فحص آلي في تجميعة لقطع تشغل الحيز نفسه أو تتلامس حيث لا يجب. يكشف أخطاء التصميم قبل التصنيع.']
]);

/* Mechanical properties of materials: added terms */
TERMS_ADD('matprops', [
    ['Elasticity', 'المرونة', 'The ability of a material to return to its original shape and size when the load is removed, as long as the load stays within the elastic range. The deformation then disappears completely (see <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Elastic deformation\',\'matprops\')">elastic deformation</a>).<span style="display:block;margin-top:.5rem"><b>Behaviour:</b> in most metals elastic strain is small (about 0.1–0.3 %) and proportional to stress (Hooke\'s law, σ = E·ε). Rubber is elastic over very large strains but not linear. The stress above which permanent deformation appears is the elastic limit, in practice close to the yield strength.</span><span style="display:block;margin-top:.5rem"><b>Energy:</b> elastic deformation stores energy that is returned on unloading — the basis of springs, snap fits and flexures.</span><span style="display:block;margin-top:.5rem"><b>Example:</b> a coil spring or a steel ruler returns to its shape after a small bend. Design keeps working stress below the elastic limit divided by a safety factor so that parts do not take a permanent set.</span><span style="display:block;margin-top:.5rem"><b>Not to be confused with:</b>  <b>stiffness</b> (<a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Stiffness\',\'matprops\')">resistance to deformation</a>): rubber is very elastic but not stiff; steel is both stiff and elastic over a small strain range. Also not <b>ductility</b> (<a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Ductility\',\'matprops\')">permanent deformation before fracture</a>) or <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Plasticity\',\'matprops\')">plasticity</a> (its opposite: deformation that remains).</span><span style="display:block;margin-top:.5rem"><b>Also called:</b> elastic behaviour. Related: modulus of elasticity (Young\'s modulus E).</span><span style="display:block;margin-top:.5rem"><b>See also:</b> <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Stress–strain curve\',\'matprops\')">Stress–strain diagram</a> — the curve that shows this property. The elastic range is the first, straight part.</span><span style="display:block;margin-top:.5rem"><b>References:</b> Hibbeler, <i>Mechanics of Materials</i>; Beer &amp; Johnston, <i>Mechanics of Materials</i>; Callister &amp; Rethwisch.</span>', 'قدرة المادة على استعادة شكلها وأبعادها الأصلية عند زوال الحمل، ما دام الحمل ضمن المجال المرن. عندها يزول التشوه كلياً (انظر <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'التشوه المرن\',\'matprops\')">التشوه المرن</a>).<span style="display:block;margin-top:.5rem"><b>السلوك:</b> في أغلب المعادن يكون الانفعال المرن صغيراً (نحو 0.1–0.3%) ويتناسب مع الإجهاد (قانون هوك σ = E·ε). المطاط مرن عند انفعالات كبيرة جداً لكن دون خطية. والإجهاد الذي يبدأ بعده التشوه الدائم هو حد المرونة، وهو عملياً قريب من حد الخضوع.</span><span style="display:block;margin-top:.5rem"><b>الطاقة:</b> يخزّن التشوه المرن طاقة تُعاد عند زوال الحمل — وهذا أساس النوابض والوصلات المطاوعة.</span><span style="display:block;margin-top:.5rem"><b>مثال:</b> نابض لولبي أو مسطرة فولاذية تعود إلى شكلها بعد انحناء صغير. ويُبقي التصميم الإجهاد العامل دون حد المرونة مقسوماً على عامل الأمان كي لا تتخذ القطع تشوهاً دائماً.</span><span style="display:block;margin-top:.5rem"><b>لا تخلطها مع:</b> <b>الصلابة</b> (<a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'الصلابة\',\'matprops\')">مقاومة التشوه</a>): المطاط شديد المرونة لكنه ليس صلباً؛ والفولاذ صلب ومرن على مدى انفعال صغير. ولا مع <b>المطيلية</b> (<a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'المطيلية\',\'matprops\')">التشوه الدائم قبل الكسر</a>) ولا مع <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'اللدونة\',\'matprops\')">اللدونة</a> (نقيضها: تشوه يبقى).</span><span style="display:block;margin-top:.5rem"><b>تسميات أخرى:</b> السلوك المرن. المرتبط: معامل المرونة (معامل يونغ E).</span><span style="display:block;margin-top:.5rem"><b>انظر أيضاً:</b> <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'مخطط الإجهاد والانفعال\',\'matprops\')">مخطط الإجهاد والانفعال</a> — المنحنى الذي تظهر عليه هذه الخاصية. والمجال المرن هو جزؤه المستقيم الأول.</span><span style="display:block;margin-top:.5rem"><b>المراجع:</b> Hibbeler؛ Beer &amp; Johnston؛ Callister &amp; Rethwisch.</span>', 'σ = E · ε  (linear elastic range) · σ [Pa or MPa], ε [–], E [GPa]<br>u = σ² / (2E)  (elastic strain energy per unit volume, J/m³)<br>E: steel ≈ 200 GPa · aluminium ≈ 70 GPa'],
    ['Plasticity', 'اللدونة', 'The ability of a material to keep a permanent deformation after the load is removed. It begins when the stress exceeds the yield strength (see <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Yield strength\',\'matprops\')">yield strength</a>) and the shape change that remains is the plastic strain (see <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Plastic deformation\',\'matprops\')">plastic deformation</a>).<span style="display:block;margin-top:.5rem"><b>Behaviour:</b> plastic flow in metals comes from slip of dislocations; it happens at almost constant volume and the material usually hardens as it deforms (strain hardening, cold work), which raises strength and hardness but lowers ductility. On unloading the elastic part springs back, the plastic part stays.</span><span style="display:block;margin-top:.5rem"><b>Example:</b> bending a sheet in a press brake, deep drawing a cup, forging a bolt head, rolling and wire drawing all rely on plasticity. Because of springback the punch must bend slightly beyond the target angle.</span><span style="display:block;margin-top:.5rem"><b>Design view:</b> machine parts are normally designed to stay elastic; a permanent set under service load is a failure of function even if the part has not broken.</span><span style="display:block;margin-top:.5rem"><b>Not to be confused with:</b>  <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Elasticity\',\'matprops\')">elasticity</a> (its opposite), <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Ductility\',\'matprops\')">ductility</a> (how much plastic strain is available before fracture) and "plastics" (polymers), which is a different word.</span><span style="display:block;margin-top:.5rem"><b>See also:</b> <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Stress–strain curve\',\'matprops\')">Stress–strain diagram</a> — the curve that shows this property. Plastic strain begins after yielding.</span><span style="display:block;margin-top:.5rem"><b>References:</b> Callister &amp; Rethwisch; Kalpakjian &amp; Schmid, <i>Manufacturing Engineering and Technology</i>; Hibbeler.</span>', 'قدرة المادة على الاحتفاظ بتشوه دائم بعد زوال الحمل. تبدأ عندما يتجاوز الإجهاد حد الخضوع (انظر <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'حد الخضوع\',\'matprops\')">حد الخضوع</a>) ويكون التغير الباقي في الشكل هو الانفعال اللدن (انظر <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'التشوه اللدن\',\'matprops\')">التشوه اللدن</a>).<span style="display:block;margin-top:.5rem"><b>السلوك:</b> ينشأ الجريان اللدن في المعادن من انزلاق الانخلاعات؛ ويحدث بحجم شبه ثابت وتتصلد المادة عادة أثناء التشوه (التصلد بالتشوه، التشغيل على البارد) فترتفع المقاومة والصلادة وتنقص المطيلية. عند رفع الحمل يرتد الجزء المرن ويبقى الجزء اللدن.</span><span style="display:block;margin-top:.5rem"><b>مثال:</b> ثني الصفيحة في مكبس الثني، السحب العميق لكأس، طرق رأس برغي، الدرفلة وسحب الأسلاك — كلها تعتمد على اللدونة. وبسبب الارتداد يجب أن ينزل المثقب قليلاً أبعد من الزاوية المطلوبة.</span><span style="display:block;margin-top:.5rem"><b>منظور التصميم:</b> تُصمَّم أجزاء الآلات عادة لتبقى مرنة؛ والتشوه الدائم تحت حمل الخدمة فشل وظيفي حتى لو لم تنكسر القطعة.</span><span style="display:block;margin-top:.5rem"><b>لا تخلطها مع:</b>  <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'المرونة\',\'matprops\')">المرونة</a> (نقيضها)، و<a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'المطيلية\',\'matprops\')">المطيلية</a> (مقدار الانفعال اللدن المتاح قبل الكسر)، وكلمة «اللدائن» (البوليمرات) وهي مفهوم آخر.</span><span style="display:block;margin-top:.5rem"><b>انظر أيضاً:</b> <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'مخطط الإجهاد والانفعال\',\'matprops\')">مخطط الإجهاد والانفعال</a> — المنحنى الذي تظهر عليه هذه الخاصية. ويبدأ الانفعال اللدن بعد الخضوع.</span><span style="display:block;margin-top:.5rem"><b>المراجع:</b> Callister &amp; Rethwisch؛ Kalpakjian &amp; Schmid؛ Hibbeler.</span>', 'ε_total = ε_elastic + ε_plastic<br>after unloading from σ: ε_plastic = ε − σ / E (unloading follows a line parallel to the elastic slope)<br>flow curve (uniform deformation): σ_true = K · ε_true^n   (n: strain-hardening exponent)'],
    ['Stiffness', 'الصلابة (الجساءة)', 'The resistance of a part or structure to deformation under load: how much force is needed per unit of deflection. It depends on the <b>material</b> (modulus E or G) <b>and the geometry</b> (area, length, second moment of area I).<span style="display:block;margin-top:.5rem"><b>Linear system:</b> k = F / δ, a force per length, in N/m or N/mm (for twisting, N·m/rad). For a bar in tension k = A·E / L; for a cantilever with a tip load k = 3·E·I / L³.</span><span style="display:block;margin-top:.5rem"><b>Material property vs part property:</b> Young\'s modulus E (<a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Modulus of elasticity\',\'matprops\')">modulus of elasticity</a>) is a property of the material; stiffness k also includes shape. A deep I-beam is far stiffer than a flat bar of the same steel.</span><span style="display:block;margin-top:.5rem"><b>Rigidity:</b> the word is used for the same idea in some contexts — flexural rigidity EI, torsional rigidity GJ, modulus of rigidity (= shear modulus G). For the idealised non-deforming body see <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Rigid body\',\'dynamics\')">Rigid body</a>.</span><span style="display:block;margin-top:.5rem"><b>Example:</b> steel and aluminium parts of identical shape: the steel one deflects about three times less (E ≈ 200 vs 70 GPa), yet specific stiffness E/ρ is almost the same for steel, aluminium and titanium, so the lightest stiff part comes from clever shape (ribs, tubes, I-sections), not from changing the metal. Stiffness controls deflection and natural frequency f = (1/2π)·√(k/m).</span><span style="display:block;margin-top:.5rem"><b>Not to be confused with:</b>  strength (stress at failure), <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Hardness\',\'matprops\')">hardness</a> (surface indentation), <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Elasticity\',\'matprops\')">elasticity</a> (recovery after load) and <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Toughness\',\'matprops\')">toughness</a>.</span><span style="display:block;margin-top:.5rem"><b>Arabic naming:</b> in this encyclopedia «الصلابة» means Stiffness; the equivalent «الجساءة» is also used in some textbooks.</span><span style="display:block;margin-top:.5rem"><b>See also:</b> <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Stress–strain curve\',\'matprops\')">Stress–strain diagram</a> — the curve that shows this property. Its slope is E, the material stiffness (not the part stiffness k).</span><span style="display:block;margin-top:.5rem"><b>References:</b> Hibbeler; Beer &amp; Johnston; Ashby, <i>Materials Selection in Mechanical Design</i>.</span>', 'مقاومة القطعة أو المنشأ للتشوه تحت الحمل: كم قوة يلزم لكل وحدة تدلٍّ. وتعتمد على <b>المادة</b> (المعامل E أو G) <b>وعلى الشكل الهندسي</b> (المساحة، الطول، عزم القصور الذاتي للمقطع I).<span style="display:block;margin-top:.5rem"><b>الجملة الخطية:</b> k = F / δ، قوة لكل طول، بوحدة N/m أو N/mm (وللالتواء N·m/rad). في قضيب مشدود k = A·E / L؛ وفي كابول بحمل عند طرفه k = 3·E·I / L³.</span><span style="display:block;margin-top:.5rem"><b>خاصية المادة مقابل خاصية القطعة:</b> معامل يونغ E (<a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'معامل المرونة\',\'matprops\')">معامل المرونة</a>) خاصية للمادة؛ أما الصلابة k فتتضمن الشكل أيضاً. فالعارضة I العميقة أصلب بكثير من شريحة مسطحة من الفولاذ نفسه.</span><span style="display:block;margin-top:.5rem"><b>الجساءة (Rigidity):</b> تُستعمل الكلمة للفكرة نفسها في سياقات: الجساءة الانحنائية EI، والجساءة الالتوائية GJ، ومعامل الجساءة (= معامل القص G). أما الجسم المثالي الذي لا يتشوه فانظر <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'الجسم الصلب\',\'dynamics\')">الجسم الصلب</a>.</span><span style="display:block;margin-top:.5rem"><b>مثال:</b> قطعتان بالشكل نفسه من الفولاذ والألمنيوم: تتدلى الفولاذية أقل بنحو ثلاث مرات (E ≈ 200 مقابل 70 GPa)، لكن الصلابة النوعية E/ρ شبه متساوية للفولاذ والألمنيوم والتيتانيوم، فتأتي القطعة الخفيفة الصلبة من ذكاء الشكل (أضلاع، أنابيب، مقاطع I) لا من تبديل المعدن. وتتحكم الصلابة بالتدلي وبالتردد الطبيعي f = (1/2π)·√(k/m).</span><span style="display:block;margin-top:.5rem"><b>لا تخلطها مع:</b>  المقاومة (الإجهاد عند الانهيار)، و<a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'الصلادة\',\'matprops\')">الصلادة</a> (انغراس السطح)، و<a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'المرونة\',\'matprops\')">المرونة</a> (الاستعادة بعد الحمل)، و<a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'المتانة\',\'matprops\')">المتانة</a>.</span><span style="display:block;margin-top:.5rem"><b>التسمية العربية:</b> في هذه الموسوعة «الصلابة» تعني Stiffness، ويُستعمل أيضاً «الجساءة» في بعض الكتب.</span><span style="display:block;margin-top:.5rem"><b>انظر أيضاً:</b> <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'مخطط الإجهاد والانفعال\',\'matprops\')">مخطط الإجهاد والانفعال</a> — المنحنى الذي تظهر عليه هذه الخاصية. وميله هو E أي صلابة المادة (وليس صلابة القطعة k).</span><span style="display:block;margin-top:.5rem"><b>المراجع:</b> Hibbeler؛ Beer &amp; Johnston؛ Ashby.</span>', 'k = F / δ   [N/m or N/mm]<br>bar in tension: k = A·E / L · cantilever, tip load: k = 3·E·I / L³ · shaft in torsion: k_t = G·J / L<br>δ: deflection · A: area · L: length · I: second moment of area · J: polar moment · G: shear modulus<br>specific stiffness = E / ρ'],
    ['Hardness', 'الصلادة (القساوة)', 'The resistance of a material\'s surface to local permanent deformation: scratching, indentation or penetration. It is not a single physical quantity: the number depends on the test method and scale, so always quote it with the scale (HBW, HV, HRC…).<span style="display:block;margin-top:.5rem"><b>Main tests:</b> Brinell (hard ball, HBW), Vickers (diamond pyramid 136°, HV), Rockwell (depth of a diamond cone or ball under a major load, HRC/HRB), Knoop (micro-hardness), Mohs (scratch scale for minerals), Shore (rubbers and plastics). See also <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Hardness test\',\'testing\')">hardness test</a>.</span><span style="display:block;margin-top:.5rem"><b>Behaviour:</b> it rises with carbon content, quenching, cold work and surface treatments, and it correlates with wear resistance and, for steels, roughly with tensile strength (UTS ≈ 3.45 × HB in MPa).</span><span style="display:block;margin-top:.5rem"><b>Example:</b> a hardened gear tooth surface of 58–62 HRC resists pitting and wear, while a softer, tougher core absorbs shock. Cutting tools must be harder than the workpiece.</span><span style="display:block;margin-top:.5rem"><b>Not to be confused with:</b>  <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Toughness\',\'matprops\')">toughness</a> (energy before fracture — hard materials are often brittle), <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Stiffness\',\'matprops\')">stiffness</a> (resistance of the part to deflection) or strength. See also <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Hardness and toughness\',\'matprops\')">hardness and toughness</a>.</span><span style="display:block;margin-top:.5rem"><b>Also called:</b> Arabic: الصلادة, and in some regions القساوة — the same concept (Hardness). The Arabic text of this encyclopedia uses «الصلادة» as the main term.</span><span style="display:block;margin-top:.5rem"><b>References:</b> Callister &amp; Rethwisch; Dieter; ISO 6506-1 (Brinell), ISO 6507-1 (Vickers), ISO 6508-1 (Rockwell), ASTM E10, E18, E92.</span>', 'مقاومة سطح المادة للتشوه الدائم الموضعي: الخدش أو الانغراس أو الاختراق. وهي ليست كمية فيزيائية واحدة: فالرقم يعتمد على طريقة الاختبار والمقياس، لذا يُذكر دائماً مع المقياس (HBW وHV وHRC…).<span style="display:block;margin-top:.5rem"><b>الاختبارات الرئيسية:</b> برينل (كرة صلبة، HBW)، فيكرز (هرم ماسي 136°، HV)، روكويل (عمق مخروط ماسي أو كرة تحت حمل رئيسي، HRC/HRB)، نووب (صلادة مجهرية)، موس (سلم الخدش للمعادن الطبيعية)، شور (المطاط واللدائن). انظر أيضاً <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'اختبار الصلادة\',\'testing\')">اختبار الصلادة</a>.</span><span style="display:block;margin-top:.5rem"><b>السلوك:</b> ترتفع بزيادة الكربون والتقسية والتشغيل على البارد والمعالجات السطحية، وترتبط بمقاومة البلى، وفي الفولاذ ترتبط تقريباً بمقاومة الشد (UTS ≈ 3.45 × HB بوحدة MPa).</span><span style="display:block;margin-top:.5rem"><b>مثال:</b> سطح سن ترس مقسّى بصلادة 58–62 HRC يقاوم التنقر والبلى، بينما اللب الأطرى والأمتن يمتص الصدمة. ويجب أن تكون أدوات القطع أصلد من القطعة المشغّلة.</span><span style="display:block;margin-top:.5rem"><b>لا تخلطها مع:</b>  <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'المتانة\',\'matprops\')">المتانة</a> (الطاقة قبل الكسر — والمواد الصلدة غالباً قصفة)، و<a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'الصلابة\',\'matprops\')">الصلابة</a> (مقاومة القطعة للتدلي) أو المقاومة. انظر أيضاً <a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'الصلادة والمتانة\',\'matprops\')">الصلادة والمتانة</a>.</span><span style="display:block;margin-top:.5rem"><b>تسميات أخرى:</b> القساوة — يُستعمل في بعض المناطق والمراجع للمفهوم نفسه (Hardness). وتعتمد هذه الموسوعة «الصلادة» مصطلحاً أساسياً و«القساوة» مرادفاً.</span><span style="display:block;margin-top:.5rem"><b>المراجع:</b> Callister &amp; Rethwisch؛ Dieter؛ ISO 6506-1 وISO 6507-1 وISO 6508-1 وASTM E10 وE18 وE92.</span>', 'HBW = 2F / ( π·D·( D − √(D² − d²) ) )  [kgf/mm²]  (D: ball Ø, d: indent Ø)<br>HV ≈ 1.8544 · F / d²  (F in kgf, d: mean diagonal in mm)<br>HRC = 100 − e / 0.002 mm  (e: permanent depth increase, mm)']
]);
TERMS_ADD('dynamics', [
    ['Rigid body', 'الجسم الصلب', 'A model in mechanics in which the distance between any two points of the body never changes, so the body only translates and rotates and its deformation is ignored.<span style="display:block;margin-top:.5rem"><b>Why it is useful:</b> it greatly simplifies statics and dynamics: a rigid body in space has 6 degrees of freedom (3 translations, 3 rotations), in a plane 3. Equilibrium needs only ΣF = 0 and ΣM = 0, and velocities follow v<sub>B</sub> = v<sub>A</sub> + ω × r<sub>B/A</sub>.</span><span style="display:block;margin-top:.5rem"><b>It is an idealisation:</b> real bodies always deform a little. The model is valid when the deformation is very small compared with the motion and dimensions of interest. It is the limit of infinite stiffness (k → ∞), not a claim that parts never deform.</span><span style="display:block;margin-top:.5rem"><b>Example:</b> finding the support reactions of a crane, the kinematics of a gear train or a four-bar linkage, the motion of a vehicle body. When stresses, deflection or vibration matter, switch to a deformable-body model (strength of materials, FEA).</span><span style="display:block;margin-top:.5rem"><b>Not to be confused with:</b>  hardness (<a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Hardness\',\'matprops\')">surface indentation</a>) or the stiffness of a real structure (<a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'Stiffness\',\'matprops\')">Stiffness</a>): a rigid body is a modelling assumption, not a material property.</span><span style="display:block;margin-top:.5rem"><b>References:</b> Meriam &amp; Kraige, <i>Engineering Mechanics: Statics / Dynamics</i>; Hibbeler, <i>Engineering Mechanics</i>.</span>', 'نموذج في الميكانيك لا تتغير فيه المسافة بين أي نقطتين من الجسم، فيقتصر حركته على الانتقال والدوران ويُهمل تشوهه.<span style="display:block;margin-top:.5rem"><b>فائدته:</b> يبسّط الاستاتيكا والديناميكا كثيراً: للجسم الصلب في الفراغ 6 درجات حرية (3 انتقالات و3 دورانات) وفي المستوي 3. ويكفي للتوازن ΣF = 0 وΣM = 0، وتُحسب السرعات من v<sub>B</sub> = v<sub>A</sub> + ω × r<sub>B/A</sub>.</span><span style="display:block;margin-top:.5rem"><b>هو مثالية نموذجية:</b> الأجسام الحقيقية تتشوه دائماً قليلاً. والنموذج صالح عندما يكون التشوه صغيراً جداً قياساً إلى الحركة والأبعاد المهمة. وهو حالة الصلابة اللانهائية (k → ∞) وليس ادعاءً بأن القطع لا تتشوه.</span><span style="display:block;margin-top:.5rem"><b>مثال:</b> إيجاد ردود أفعال مساند رافعة، أو حركيات سلسلة تروس أو آلية رباعية الحلقات، أو حركة هيكل مركبة. وعندما تهم الإجهادات أو التدلي أو الاهتزاز يُنتقل إلى نموذج الجسم القابل للتشوه (مقاومة المواد، العناصر المنتهية).</span><span style="display:block;margin-top:.5rem"><b>لا تخلطه مع:</b>  الصلادة (<a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'الصلادة\',\'matprops\')">انغراس السطح</a>) أو صلابة منشأ حقيقي (<a href="#" class="underline text-primary-600 dark:text-primary-400" onclick="return encSee(\'الصلابة\',\'matprops\')">الصلابة</a>): الجسم الصلب فرضية نمذجة وليس خاصية مادة.</span><span style="display:block;margin-top:.5rem"><b>المراجع:</b> Meriam &amp; Kraige؛ Hibbeler (Engineering Mechanics).</span>', '|r_i − r_j| = constant for every pair of points<br>DOF: 3D = 6 (3 translations + 3 rotations), plane = 3<br>statics: ΣF = 0 , ΣM = 0 · kinematics: v_B = v_A + ω × r_B/A']
]);
